	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_REGULAR_CANDLES = state -> state.getValue(BlockStateProperties.LIT) ? 3 * (Integer) state.getValue(BlockStateProperties.CANDLES) : 0;
	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_SOUL_CANDLES = state -> state.getValue(BlockStateProperties.LIT) ? 2 * (Integer) state.getValue(BlockStateProperties.CANDLES) : 0;
	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_REGULAR_TORCHES = state -> state.getValue(BlockStateProperties.LIT) ? 14 : 0;
	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_SOUL_TORCHES = state -> state.getValue(BlockStateProperties.LIT) ? 10 : 0;
	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_REGULAR_LANTERNS = state -> state.getValue(BlockStateProperties.LIT) ? 14 : 0;
	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_SOUL_LANTERNS = state -> state.getValue(BlockStateProperties.LIT) ? 10 : 0;
	public static final ToIntFunction<BlockState> STATE_TO_LUMINANCE_TRIAL_SPAWNERS = state -> state.getValue(TrialSpawnerBlock.STATE).lightLevel();

