	private static InteractiveTriggerCandleBlock interactiveTriggerCandle(ResourceKey<Block> block_key, SimpleParticleType flameParticle, MapColor mapColor, ToIntFunction<BlockState> luminance) {
		return new InteractiveTriggerCandleBlock(flameParticle, BlockBehaviour.Properties.of().setId(block_key).mapColor(mapColor).requiresCorrectToolForDrops().strength(-1.0f, 3600000.0f).noOcclusion().noLootTable().lightLevel(luminance));
	}

	private static Block registerAestheticDecoratedPotBlock(ResourceKey<Block> block_key, ResourceKey<Item> item_key, Block block, List<ResourceKey<CreativeModeTab>> itemGroupList) {
		Registry.register(BuiltInRegistries.ITEM, item_key, new BlockItem(block, new Item.Properties().component(DataComponents.POT_DECORATIONS, PotDecorations.EMPTY)));
		for (ResourceKey<CreativeModeTab> itemGroup : itemGroupList) {
			CreativeModeTabEvents.modifyOutputEvent(itemGroup).register(content -> content.accept(block));
		}
		return Registry.register(BuiltInRegistries.BLOCK, block_key, block);
	}

	private static Block registerStandingAndWallBlock(ResourceKey<Block> block_key, ResourceKey<Item> item_key, Block wallBlock, Direction attachmentDirection, Block block, List<ResourceKey<CreativeModeTab>> creativeModeTabList, Block... alternatives) {
		Item blockItem = Registry.register(BuiltInRegistries.ITEM, item_key, new StandingAndWallBlockItem(block, wallBlock, attachmentDirection, new Item.Properties().setId(item_key)));
		for (ResourceKey<CreativeModeTab> creativeModeTab : creativeModeTabList) {
			CreativeModeTabEvents.modifyOutputEvent(creativeModeTab).register(content -> content.accept(block));
		}
		for (Block alternative : alternatives) {
			Item.BY_BLOCK.put(alternative, blockItem);
		}
		return Registry.register(BuiltInRegistries.BLOCK, block_key, block);
	}

	private static Block registerBlock(ResourceKey<Block> block_key, ResourceKey<Item> item_key, Block block, List<ResourceKey<CreativeModeTab>> creativeModeTabList, Block... alternatives) {
		Item blockItem = Registry.register(BuiltInRegistries.ITEM, item_key, new BlockItem(block, new Item.Properties().setId(item_key)));
		for (ResourceKey<CreativeModeTab> creativeModeTab : creativeModeTabList) {
			CreativeModeTabEvents.modifyOutputEvent(creativeModeTab).register(content -> content.accept(block));
		}
		for (Block alternative : alternatives) {
			Item.BY_BLOCK.put(alternative, blockItem);
		}
		return Registry.register(BuiltInRegistries.BLOCK, block_key, block);
	}

	private static Block registerBlockWithoutItem(ResourceKey<Block> block_key, Block block) {
		return Registry.register(BuiltInRegistries.BLOCK, block_key, block);
	}

